import pytest
from snake import engine, render


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
    (5, 3),
])
def test_returns_correct_number_of_lines(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    assert len(frame) == height + 2


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
    (5, 3),
])
def test_each_line_has_correct_length(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    for line in frame:
        assert len(line) == width + 2


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_border_characters_present(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    top_line = frame[0]
    bottom_line = frame[-1]
    for line in [top_line, bottom_line]:
        assert line.startswith("+") or line.startswith("┌")
        assert line.endswith("+") or line.endswith("┐")
        assert "─" in line or "-" in line


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_side_border_characters_present(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    for line in frame[1:-1]:
        assert line.startswith("|") or line.startswith("│")
        assert line.endswith("|") or line.endswith("│")


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_head_character_present(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    head_x = game.snake[0][0]
    head_y = game.snake[0][1]
    line_index = head_y + 1
    col_index = head_x + 1
    head_char = frame[line_index][col_index]
    assert head_char == "@"


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_body_character_present(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    for body_cell in game.snake[1:]:
        x, y = body_cell
        line_index = y + 1
        col_index = x + 1
        cell_char = frame[line_index][col_index]
        assert cell_char == "o"


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_head_and_body_use_different_characters(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    head_x, head_y = game.snake[0]
    body_x, body_y = game.snake[1]
    head_line = frame[head_y + 1][head_x + 1]
    body_line = frame[body_y + 1][body_x + 1]
    assert head_line != body_line


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_head_and_body_use_different_characters_than_food(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    head_x, head_y = game.snake[0]
    food_x, food_y = game.food if game.food else (0, 0)
    head_char = frame[head_y + 1][head_x + 1]
    food_char = frame[food_y + 1][food_x + 1]
    assert head_char != food_char


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_food_character_present(width, height):
    game = engine.Game(width, height, seed=42)
    if game.food is None:
        pytest.skip("Board is full")
    frame = render.render(game)
    food_x, food_y = game.food
    line_index = food_y + 1
    col_index = food_x + 1
    food_char = frame[line_index][col_index]
    assert food_char == "*"


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_empty_cells_are_spaces(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    empty_positions = []
    for y in range(height):
        for x in range(width):
            if (x, y) not in game.snake and game.food != (x, y):
                empty_positions.append((x, y))

    for x, y in empty_positions:
        line_index = y + 1
        col_index = x + 1
        cell_char = frame[line_index][col_index]
        assert cell_char == " "


@pytest.mark.parametrize("width,height", [
    (10, 8),
    (20, 15),
])
def test_cell_coordinates_map_correctly(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    for x, y in [(0, 0), (width-1, 0), (0, height-1), (width-1, height-1), (5, 3)]:
        line_index = y + 1
        col_index = x + 1
        assert frame[line_index][col_index] == " " or \
               (x, y) in game.snake or (game.food and game.food == (x, y))


@pytest.mark.parametrize("width,height", [
    (3, 2),
])
def test_small_board_rendered_correctly(width, height):
    game = engine.Game(width, height, seed=42)
    frame = render.render(game)
    assert len(frame) == height + 2
    for line in frame:
        assert len(line) == width + 2


@pytest.mark.parametrize("width,height", [
    (10, 8),
])
def test_can_set_snake_position_and_render(width, height):
    game = engine.Game(width, height, seed=42)
    game.snake = [(5, 4), (4, 4)]
    frame = render.render(game)
    head_x, head_y = game.snake[0]
    line_index = head_y + 1
    col_index = head_x + 1
    assert frame[line_index][col_index] == "@"


@pytest.mark.parametrize("width,height", [
    (10, 8),
])
def test_can_set_food_position_and_render(width, height):
    game = engine.Game(width, height, seed=42)
    if game.food:
        game.food = (3, 5)
    frame = render.render(game)
    food_x, food_y = game.food
    line_index = food_y + 1
    col_index = food_x + 1
    assert frame[line_index][col_index] == "*"


@pytest.mark.parametrize("width,height", [
    (3, 2),
])
def test_full_board_has_no_food_marker(width, height):
    game = engine.Game(width, height, seed=42)
    # Fill the board so no food can spawn
    game.snake = [(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)]
    game.food = None
    frame = render.render(game)
    for line in frame:
        assert "*" not in line
